// Additional discoveries. Historical models are explicitly distinguished from current physics.
const additionalScientists=[
{id:'aristotle',name:'Aristotle',era:'early',field:'ANCIENT COSMOLOGY',glyph:'⊕',title:'When Earth was the center',formula:'A historical worldview, not a modern physical law',desc:'Aristotle described a stationary Earth surrounded by rotating heavens. This schematic turns nested circles around Earth to illustrate that ancient worldview. It is a historical model, not an accurate account of planetary motion.',kind:'ancient',label:'Animation speed',min:.3,max:2,step:.1,value:1},
{id:'archimedes',name:'Archimedes',era:'early',field:'BUOYANCY',glyph:'ρgV',title:'The water pushes back',formula:'Fᵦ = ρfluid g Vdisplaced',desc:'Buoyancy equals the weight of displaced fluid. For this uniform block in water, the fraction submerged at floating equilibrium equals its density relative to water. Above a density ratio of one, the block sinks to the floor.',kind:'buoyancy',label:'Block / water density',min:.2,max:1.4,step:.05,value:.6},
{id:'ptolemy',name:'Claudius Ptolemy',era:'early',field:'GEOCENTRIC ASTRONOMY',glyph:'◯ + ◯',title:'A circle riding a circle',formula:'Schematic epicycle: r(t) = R(t) + rₑ(t)',desc:'Ptolemaic astronomy used combinations of circular motions to account for apparent planetary motion. This simplified epicycle can make loops around a stationary Earth. It is not a reconstruction of the full historical system, which included additional geometric devices.',kind:'epicycle',label:'Epicycle radius / main radius',min:.1,max:.6,step:.05,value:.35},
{id:'copernicus',name:'Nicolaus Copernicus',era:'early',field:'HELIOCENTRIC ASTRONOMY',glyph:'☉',title:'Move the observer. Change the picture.',formula:'Relative position = planet position − Earth position',desc:'Copernicus placed Earth among the planets moving around the Sun. Here a faster inner Earth overtakes a slower outer planet. The dashed sightline changes direction even though both planets keep moving forward. Circular paths and time are simplified.',kind:'heliocentric',label:'Outer orbital radius (Earth = 1)',min:1.3,max:2,step:.05,value:1.52},
{id:'brahe',name:'Tycho Brahe',era:'early',field:'HISTORICAL ASTRONOMY',glyph:'⊕ → ☉',title:'A universe between two models',formula:'Historical geoheliocentric model',desc:'Tycho’s model kept Earth stationary: the Sun traveled around Earth while other planets traveled around the Sun. This schematic shows that hybrid arrangement. His precise observations later helped Kepler test planetary models.',kind:'tychonic',label:'Animation speed',min:.3,max:2,step:.1,value:1},
{id:'carnot',name:'Sadi Carnot',field:'HEAT ENGINES',glyph:'1 − Tc/Th',title:'Even a perfect engine has a limit',formula:'ηmax = 1 − Tcold / Thot',desc:'A reversible heat engine operating between two reservoirs has the Carnot efficiency. The cold reservoir stays at 300 K. Raise the hot temperature to change the maximum fraction of incoming heat that can become work. Real engines perform below this limit.',kind:'engine',label:'Hot reservoir (K)',min:350,max:1000,step:10,value:600},
{id:'joule',name:'James Prescott Joule',field:'WORK & HEAT',glyph:'W → ΔU',title:'Stirring a little warmth into water',formula:'ΔT = W / (mc)',desc:'Joule connected mechanical work and heating. This ideal insulated model turns 4,184 joules of paddle work into internal energy of water, using c = 4,184 J/(kg·K). More water means a smaller temperature rise for the same work. The cycle repeats for illustration.',kind:'paddle',label:'Water mass (kg)',min:.5,max:3,step:.1,value:1},
{id:'clausius',name:'Rudolf Clausius',field:'ENTROPY',glyph:'ΔS ≥ 0',title:'Heat has a direction',formula:'ΔS = C ln(T₁/T₁₀) + C ln(T₂/T₂₀)',desc:'Two isolated bodies with equal, constant heat capacities exchange heat until their temperatures agree. Total energy stays fixed while total entropy rises. One begins at 300 K; set the other’s initial temperature. Time and heat capacity are normalized.',kind:'entropy',label:'Initial hot body (K)',min:350,max:700,step:10,value:600},
{id:'kelvin',name:'William Thomson · Lord Kelvin',field:'ABSOLUTE TEMPERATURE',glyph:'T ≥ 0 K',title:'A temperature scale with a true zero',formula:'⟨Ekin⟩ = 3kBT / 2',desc:'Kelvin developed an absolute thermodynamic temperature scale. This classical ideal-gas illustration links temperature to mean translational kinetic energy: raising T makes the particles move faster. It does not model quantum behavior near absolute zero.',kind:'thermal-motion',label:'Gas temperature (K)',min:100,max:900,step:20,value:300},
{id:'gibbs',name:'Josiah Willard Gibbs',field:'FREE ENERGY',glyph:'ΔG = ΔH − TΔS',title:'When a process becomes favorable',formula:'ΔG = ΔH − TΔS',desc:'At fixed temperature and pressure, a negative Gibbs free-energy change favors a process. This illustrative example holds ΔH = 20 kJ/mol and ΔS = 0.05 kJ/(mol·K), so the sign changes at 400 K. Favorability does not tell you how fast a process happens.',kind:'free-energy',label:'Temperature (K)',min:200,max:700,step:10,value:450},
{id:'fourier',name:'Joseph Fourier',field:'HEAT DIFFUSION',glyph:'∂T/∂t',title:'A hot spot smooths itself out',formula:'∂T/∂t = α ∂²T/∂x²',desc:'A rod starts with a smooth temperature bump and has fixed-temperature ends. The heat equation predicts the decay of that bump. Raise thermal diffusivity to make it flatten faster. Position, temperature, and time are normalized; the animation periodically restarts.',kind:'diffusion',label:'Thermal diffusivity',min:.2,max:2,step:.1,value:.7},
{id:'heisenberg',name:'Werner Heisenberg',era:'modern',field:'UNCERTAINTY',glyph:'Δx Δp ≥ ℏ/2',title:'Sharper here. Wider there.',formula:'Δx Δp ≥ ℏ / 2',desc:'Position and momentum cannot both have arbitrarily narrow distributions in a quantum state. These Gaussian distributions saturate the bound: with ℏ = 1, Δp = 1/(2Δx). This is a property of the state, not simply a story about faulty instruments. Each plot uses the same horizontal scale and its own vertical normalization.',kind:'uncertainty',label:'Position spread Δx',min:.3,max:1.6,step:.05,value:.7},
{id:'debroglie',name:'Louis de Broglie',era:'modern',field:'MATTER WAVES',glyph:'λ = h/p',title:'Matter gets a wavelength',formula:'λ = h / p',desc:'De Broglie associated a wavelength with momentum. In these normalized units h = 1: increasing momentum shortens the wavelength. The moving curve represents a wave phase, not a material particle traveling along a wavy path.',kind:'matter-wave',label:'Momentum (normalized)',min:1,max:6,step:.1,value:3},
{id:'pauli',name:'Wolfgang Pauli',era:'modern',field:'EXCLUSION PRINCIPLE',glyph:'↑↓',title:'No identical seats',formula:'No two identical fermions occupy the same quantum state',desc:'Each spatial orbital here has two distinct spin states. Opposite-spin electrons can share an orbital; two electrons cannot share the same complete state. Fill this simplified ladder from low energy upward. Real multi-electron atoms have additional structure and interactions.',kind:'exclusion',label:'Electrons',min:1,max:8,step:1,value:5},
{id:'fermi',name:'Enrico Fermi',era:'modern',field:'FERMION STATISTICS',glyph:'f(E)',title:'The edge that temperature softens',formula:'f(E) = 1 / [exp((E − μ)/kBT) + 1]',desc:'Fermi–Dirac statistics describe the mean occupation of a single-particle state for noninteracting fermions in equilibrium. This plot fixes μ = 0 and kB = 1. Heating broadens the sharp occupation boundary, while occupation of each state stays between zero and one.',kind:'fermi',label:'Temperature (normalized)',min:.05,max:1,step:.05,value:.2},
{id:'meitner',name:'Lise Meitner',era:'modern',field:'NUCLEAR FISSION',glyph:'Δm c²',title:'A nucleus can split',formula:'Released energy = Δm c²',desc:'Meitner and Otto Frisch explained nuclear fission after Hahn and Strassmann’s chemical results. This schematic shows one possible uranium-235 fission channel after neutron absorption: barium-141, krypton-92, and three neutrons. It is a conceptual animation, not a reaction-rate or reactor model.',kind:'fission',label:'Playback speed',min:.5,max:2,step:.1,value:1}
];
function drawAdditionalDiscovery(s,v,t,w,h,x){
 const cx=w/2,cy=h/2,gold='#e5cb86',purple='#cbb1f4',teal='#91d3cb',muted='#b9abc9';
 const ring=(a,b,r,col=purple)=>{x.strokeStyle=col+'88';x.beginPath();x.arc(a,b,r,0,Math.PI*2);x.stroke()};
 if(s.kind==='ancient'){
  const r=Math.min(w*.32,h*.33);dot(x,cx,cy,13,teal);label(x,'Earth',cx-17,cy+30);
  for(let i=1;i<=3;i++){let radius=r*i/3;ring(cx,cy,radius);let a=t*v/(i*.8);dot(x,cx+radius*Math.cos(a),cy+radius*Math.sin(a),4+i/2,i===2?gold:purple)}label(x,'HISTORICAL MODEL',18,24,gold);return true;
 }
 if(s.kind==='buoyancy'){
  const top=h*.42,floor=h-42,size=Math.min(62,h*.2),sub=Math.min(1,v),target=v<=1?top-size*(1-sub):floor-size;
  x.fillStyle='#397b883f';x.fillRect(25,top,w-50,floor-top);line(x,25,top,w-25,top,teal);line(x,25,floor,w-25,floor,muted);
  let y=target+Math.sin(t*2)*Math.exp(-t*.7)*10;x.fillStyle=gold;x.fillRect(cx-size/2,y,size,size);let arrow=Math.min(55,30*v);line(x,cx+size,y+size/2,cx+size,y+size/2+arrow,gold,3);line(x,cx-size,y+size/2,cx-size,y+size/2-30*sub,teal,3);
  label(x,v<=1?'Floating equilibrium':'Sinks: weight > buoyancy',18,24);label(x,v<=1?Math.round(sub*100)+'% submerged':'Resting on the bottom',18,h-16,teal);return true;
 }
 if(['epicycle','heliocentric','tychonic'].includes(s.kind)){
  const r=Math.min(w*.24,h*.29);label(x,s.kind==='heliocentric'?'HELIOCENTRIC VIEW':'HISTORICAL MODEL',18,24,gold);
  if(s.kind==='epicycle'){ring(cx,cy,r);const a=t*.45,b=-t*1.9,ex=cx+r*Math.cos(a),ey=cy+r*Math.sin(a);ring(ex,ey,r*v);dot(x,cx,cy,9,teal);dot(x,ex+r*v*Math.cos(b),ey+r*v*Math.sin(b),6,gold);line(x,cx,cy,ex,ey,muted,1);label(x,'Earth',cx-17,cy+25)}
  if(s.kind==='heliocentric'){const inner=r/v,outer=r,a=t*.6,b=t*.6/v**1.5,ex=cx+inner*Math.cos(a),ey=cy+inner*Math.sin(a),px=cx+outer*Math.cos(b),py=cy+outer*Math.sin(b);ring(cx,cy,inner);ring(cx,cy,outer);dot(x,cx,cy,10,gold);dot(x,ex,ey,6,teal);dot(x,px,py,6,purple);x.setLineDash([4,5]);line(x,ex,ey,px,py,muted,1);x.setLineDash([]);label(x,'Earth',ex-18,ey+22);label(x,'Sun',cx-12,cy-18);label(x,'outer planet',18,h-18,purple)}
  if(s.kind==='tychonic'){let a=t*.35*v,ex=cx+r*.65*Math.cos(a),ey=cy+r*.65*Math.sin(a);ring(cx,cy,r*.65);ring(ex,ey,r*.65);dot(x,cx,cy,9,teal);dot(x,ex,ey,9,gold);dot(x,ex+r*.65*Math.cos(t*v),ey+r*.65*Math.sin(t*v),5,purple);label(x,'Earth fixed',cx-32,cy+24);label(x,'Sun',ex-10,ey-17)}return true;
 }
 if(s.kind==='engine'){
  const eta=1-300/v;label(x,'HOT: '+v+' K',20,27,gold);label(x,'COLD: 300 K',20,h-19,teal);x.fillStyle='#e5cb8622';x.fillRect(20,40,w-40,30);x.fillStyle='#91d3cb22';x.fillRect(20,h-75,w-40,30);ring(cx,cy,30);for(let i=0;i<4;i++){let a=t+i*Math.PI/2;line(x,cx,cy,cx+Math.cos(a)*25,cy+Math.sin(a)*25,gold,3)}
  line(x,cx,70,cx,cy-32,gold,4);line(x,cx,cy+32,cx,h-75,teal,4);line(x,cx+32,cy,w-35,cy,purple,3);dot(x,cx,70+(t%1)*(cy-102),4,gold);label(x,'work',w-62,cy-15,purple);label(x,'η = '+Math.round(eta*100)+'%',20,cy);return true;
 }
 if(s.kind==='paddle'){
  let progress=(t%8)/8,r=Math.min(45,h*.15);x.fillStyle='#397b8844';x.fillRect(w*.2,h*.3,w*.6,h*.5);line(x,cx,45,cx,cy+30,purple,3);for(let i=0;i<4;i++){let a=t*3+i*Math.PI/2;line(x,cx,cy,cx+Math.cos(a)*r,cy+Math.sin(a)*r,gold,5)}label(x,'Work: '+Math.round(progress*4184)+' J',18,24,gold);label(x,'ΔT: '+(progress/v).toFixed(2)+' K',18,h-18,teal);return true;
 }
 if(s.kind==='entropy'){
  const p=1-Math.exp(-(t%12)*.4),mid=(v+300)/2,hot=v+(mid-v)*p,cold=300+(mid-300)*p,ds=Math.log(hot/v)+Math.log(cold/300);
  for(let i=0;i<2;i++){let a=20+i*w/2;x.fillStyle=i?'#397b8866':'#b3816266';x.fillRect(a,70,w/2-40,h-130);label(x,Math.round(i?cold:hot)+' K',a+12,100,i?teal:gold)}line(x,cx-20,cy,cx+20,cy,purple,3);dot(x,cx-20+(t%1)*40,cy,4,gold);label(x,'Total entropy rises',18,26);label(x,'ΔS / C = '+ds.toFixed(3),18,h-20,purple);return true;
 }
 if(s.kind==='thermal-motion'){
  const speed=Math.sqrt(v/300);x.strokeStyle=muted;x.strokeRect(20,48,w-40,h-100);for(let i=0;i<32;i++){let u=(i*.618+t*speed*(.1+(i%5)*.02))%2,z=(i*.379+t*speed*(.13+(i%7)*.01))%2;dot(x,25+(u>1?2-u:u)*(w-50),54+(z>1?2-z:z)*(h-114),3,i%3?teal:gold)}label(x,'T = '+v+' K',18,25);label(x,'mean kinetic energy ∝ T',18,h-18);return true;
 }
 if(s.kind==='free-energy'){
  const toX=T=>35+(T-200)/500*(w-70),toY=G=>cy-G*(h*.3/15);line(x,35,cy,w-35,cy,muted,1);line(x,toX(200),toY(10),toX(700),toY(-15),purple,3);dot(x,toX(v),toY(20-v*.05),6+Math.sin(t*2),gold);label(x,'ΔG = '+(20-v*.05).toFixed(1)+' kJ/mol',18,26,gold);label(x,v>400?'Thermodynamically favorable':v===400?'ΔG = 0':'Not favorable in this direction',18,h-17);label(x,'200 → 700 K',w-116,h-39);return true;
 }
 if(s.kind==='diffusion'){
  const amp=Math.exp(-v*(t%10)*.35);for(let i=0;i<80;i++){const u=i/79,temp=Math.sin(Math.PI*u)*amp;x.fillStyle=`rgb(${Math.round(65+180*temp)},${Math.round(150-45*temp)},${Math.round(195-100*temp)})`;x.fillRect(25+u*(w-50),h*.65,(w-50)/79+1,25)}path(x,u=>h*.56-Math.sin(Math.PI*u)*amp*h*.35,w,h,gold);label(x,'Fixed-temperature ends',18,24);label(x,'hot spot → equilibrium',18,h-18);return true;
 }
 if(s.kind==='uncertainty'){
  const sigmas=[v,1/(2*v)],left=26,right=w-22,span=right-left;for(let k=0;k<2;k++){const base=h*(k?.85:.43);line(x,left,base,right,base,muted,1);path(x,u=>base-Math.exp(-1*((u-.5)*8)**2/(2*sigmas[k]**2))*h*.22,w,h,k?gold:teal,left,right);label(x,(k?'Momentum Δp = ':'Position Δx = ')+sigmas[k].toFixed(2),left,base-h*.26,k?gold:teal);const u=.5+Math.sin(t*.6)*sigmas[k]/8;dot(x,left+u*span,base-Math.exp(-1*((u-.5)*8)**2/(2*sigmas[k]**2))*h*.22,3,purple)}label(x,'Δx × Δp = 0.50 (ℏ = 1)',18,h-12);return true;
 }
 if(s.kind==='matter-wave'){path(x,u=>cy-Math.sin(2*Math.PI*v*u-t*2)*h*.22,w,h,teal);label(x,'λ = '+(1/v).toFixed(2)+' (h = 1)',18,26,gold);label(x,'Wave phase, not a particle path',18,h-18);return true}
 if(s.kind==='exclusion'){
  for(let i=0;i<4;i++){const y=h-50-i*(h-105)/3;line(x,45,y,w-45,y,muted,1);label(x,'E'+(i+1),20,y+4);for(let spin=0;spin<2;spin++){const occupied=v>i*2+spin,a=w*(spin?.64:.4);if(occupied){dot(x,a,y-13,8,spin?purple:teal);label(x,spin?'↓':'↑',a-4,y-9,'#171322')}else ring(a,y-13,8,'#665577')}}label(x,'Two spin states per orbital',18,24);return true;
 }
 if(s.kind==='fermi'){
  const base=h-45;path(x,u=>base-(1/(Math.exp(((u-.5)*6)/v)+1))*(h-95),w,h,teal);line(x,cx,45,cx,base,purple,1);dot(x,cx,base-(h-95)/2,4+Math.sin(t)*.5,gold);label(x,'occupation: 0 to 1',18,25);label(x,'μ = 0',cx+7,h-20);label(x,'energy →',w-95,25);return true;
 }
 if(s.kind==='fission'){
  const phase=t*v%6,split=phase>2,travel=Math.min(1,(phase-2)/3);if(!split){dot(x,cx,cy,25,gold);dot(x,30+(cx-55)*phase/2,cy,4,teal);label(x,'neutron + U-235',18,26)}else{dot(x,cx-travel*w*.26,cy-25*travel,19,gold);dot(x,cx+travel*w*.26,cy+25*travel,15,purple);for(let i=0;i<3;i++){let a=-Math.PI/2+i*2*Math.PI/3;dot(x,cx+Math.cos(a)*travel*h*.37,cy+Math.sin(a)*travel*h*.37,3,teal)}label(x,'Ba-141',cx-travel*w*.26-22,cy-25*travel-29);label(x,'Kr-92',cx+travel*w*.26-20,cy+25*travel+34);label(x,'One possible fission channel',18,26)}label(x,'Conceptual animation',18,h-18);return true;
 }
 return false;
}
